import React, { useState } from "react";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import EvaluatorSideBar from "../components/EvaluatorSideBar";
import "./EvaluateProjects.css";

const EvaluateProjects = () => {
  // Hardcoded Group Details for Evaluation
  const group = {
    name: "Group A",
    project: "AI-based Attendance System",
    members: ["Student 1", "Student 2", "Student 3"],
  };

  // State for evaluation criteria
  const [scores, setScores] = useState({
    innovation: "",
    documentation: "",
    presentation: "",
  });

  const [feedback, setFeedback] = useState("");

  const handleScoreChange = (e) => {
    setScores({ ...scores, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Evaluation Submitted:", scores, feedback);
    alert("Evaluation submitted successfully!");
  };

  return (
    <div className="dashboard-container">
      <Navbar />
      <div className="dashboard-layout">
        <EvaluatorSidebar />

        {/* Main Content */}
        <main className="dashboard-main">
          <div className="hero-section">
            <h1>Evaluate Project</h1>
            <p>Assess the project based on various evaluation criteria.</p>
          </div>

          <div className="dashboard-content">
            <div className="evaluation-section">
              <h2>{group.project}</h2>
              <p><strong>Group Name:</strong> {group.name}</p>
              <p><strong>Members:</strong> {group.members.join(", ")}</p>

              <form className="evaluation-form" onSubmit={handleSubmit}>
                <div className="form-group">
                  <label>Innovation (Out of 10):</label>
                  <input type="number" name="innovation" value={scores.innovation} onChange={handleScoreChange} min="0" max="10" required />
                </div>

                <div className="form-group">
                  <label>Documentation (Out of 10):</label>
                  <input type="number" name="documentation" value={scores.documentation} onChange={handleScoreChange} min="0" max="10" required />
                </div>

                <div className="form-group">
                  <label>Presentation (Out of 10):</label>
                  <input type="number" name="presentation" value={scores.presentation} onChange={handleScoreChange} min="0" max="10" required />
                </div>

                <div className="form-group">
                  <label>Feedback:</label>
                  <textarea value={feedback} onChange={(e) => setFeedback(e.target.value)} placeholder="Write your feedback here..." required />
                </div>

                <button type="submit" className="submit-btn">Submit Evaluation</button>
              </form>
            </div>
          </div>
        </main>
      </div>
      <Footer />
    </div>
  );
};

export default EvaluateProjects;
